// The Heads of the Exile from the house of Bustenai to Chizkiya Gaon, and the
// figures of Bavel and Persia in the days of the Geonim (the orange boxes on
// the poster, with Anan ben David and Binyamin al-Nahawandi). Mostly following
// Moshe Gintzler's study of the line of the Heads of the Exile.
const { L, sec, to } = require('./helpers');
const T2 = require('./tree-checklist-talmud');

const E = (e) => {
  const row = T2.find((r) => r[0] === e.spot2);
  if (!row) throw new Error(`"${e.spot2}" is not in the Talmud tree checklist`);
  return { gender: 'male', roles: [], ...e, color: e.color || row[1] };
};
const F = (e) => E({ gender: 'female', ...e });
